179			{"type":"health","service":"svc-b","instanceId":"i1","expectedRevision":1,"sequence":3,"healthy":true},
180			{"type":"health","service":"svc-a","instanceId":"i1","expectedRevision":1,"sequence":4,"healthy":false,"reason":"误报重发"},
181			{"type":"health","service":"svc-a","instanceId":"i1","expectedRevision":1,"sequence":10,"healthy":false,"reason":"误报重发"},
182			{"type":"health","service":"svc-b","instanceId":"i1","expectedRevision":1,"sequence":4,"healthy":true},
183			{"type":"select","service":"svc-a","expectedRevision":1},
184			{"type":"select","service":"svc-b","expectedRevision":1}
185		]}`
186		out, code := runRegisterWith(t, input)
187		if code != 1 {
188			t.Fatalf("batch contains failures, exit code: %d, output: %s", code, out)
189		}
190		var got registerOutput
191		if err := json.Unmarshal([]byte(out), &got); err != nil {
192			t.Fatalf("output is not JSON: %v\n%s", err, out)
193		}
194		if len(got.Results) != 9 {
195			t.Fatalf("results: %+v", got.Results)
196		}
197	
198		// 2-3: each service's i1 accepts its own healthy observation at its own
199		// sequence; neither report bumps a registration revision.
200		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 10 {
201			t.Fatalf("result 2 svc-a healthy at 10: %+v", r)
202		}
203		if r := got.Results[3]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 3 {
204			t.Fatalf("result 3 svc-b healthy at its own sequence 3: %+v", r)
205		}
206	
207		// 4: stale against svc-a's own current sequence 10 — svc-b's 3 is not
208		// consulted — and the failure reports svc-a's sequence.
209		if r := got.Results[4]; r.OK || r.Error != "stale" ||
210			r.Reason != "sequence 4 is older than the current sequence 10" ||
211			r.Sequence != 10 || r.Revision != 1 {
