215		if r := got.Results[5]; r.OK || r.Error != "conflict" ||
216			r.Reason != "sequence 10 already used with different health content" ||
217			r.Sequence != 10 || r.Revision != 1 {
218			t.Fatalf("result 5 conflict against svc-a's own record: %+v", r)
219		}
