224		if r := got.Results[6]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 4 {
225			t.Fatalf("result 6 svc-b healthy at its own sequence 4: %+v", r)
226		}
227	
228		// 7-8: both services still select their own healthy i1 with its own
229		// latest accepted sequence — the rejected "unhealthy" reports knocked
230		// neither record out.
231		if r := got.Results[7]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 10 || r.Revision != 1 {
232			t.Fatalf("result 7 svc-a keeps its accepted record: %+v", r)
233		}
234		if r := got.Results[8]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 4 || r.Revision != 1 {
235			t.Fatalf("result 8 svc-b keeps its own record: %+v", r)
236		}
237	
238		// The final list holds only the accepted observations: both i1 healthy,
239		// svc-a at sequence 10 and svc-b at sequence 4, no reason anywhere, and
240		// both revisions still 1.
241		if len(got.Services) != 2 {
242			t.Fatalf("services: %+v", got.Services)
243		}
244		wantInsts := map[string]registerInstance{
245			"svc-a": {ID: "i1", Address: "h1:8080", Health: "healthy", Sequence: 10},
246			"svc-b": {ID: "i1", Address: "h1:8080", Health: "healthy", Sequence: 4},
247		}
248		for _, svc := range got.Services {
249			want, ok := wantInsts[svc.Service]
250			if !ok {
251				t.Fatalf("unexpected service: %+v", svc)
252			}
253			if svc.Revision != 1 || len(svc.Instances) != 1 || svc.Instances[0] != want {
254				t.Fatalf("service %s: got %+v want revision 1 with instance %+v", svc.Service, svc, want)
255			}
256		}
257	}
