29	// assertRangeInvalid marks the result as an expectedRevision range rejection:
30	// invalid kind, a reason stating the range and the submitted value, the
31	// service's current revision, and no expected/actual comparison fields.
32	func assertRangeInvalid(t *testing.T, r registerResult, currentRevision int, submitted string) {
33		t.Helper()
