279	// tokens; TestRegisterExpectedRevisionBeyondInt64 covers it.
280	func TestRegisterOutOfRangeFieldPrecedence(t *testing.T) {
281		const overflow32 = "4294967297" // parses as int64; exceeds int only on 32-bit
282	
283		// Earlier-checked fields win on every architecture (on 64-bit the value is
