285		out, code := runRegisterWith(t, `{"requests":[
286			{"type":"register","service":"  ","expectedRevision":`+overflow32+`,"instances":[]},
287			{"type":"health","service":"svc","instanceId":" ","expectedRevision":`+overflow32+`,"sequence":1,"healthy":true},
288			{"type":"select","service":"  ","expectedRevision":`+overflow32+`},
289			{"type":"select","service":"svc","expectedRevision":`+overflow32+`,"sessionKey":null}
290		]}`)
291		if code != 1 {
292			t.Fatalf("exit code: %d", code)
293		}
294		got := decodeRegisterOutput(t, out)
295		want := []string{
296			"service name must not be empty",
297			"instance id must not be empty",
298			"service name must not be empty",
299			"sessionKey must be a string, not null",
300		}
301		for i, sub := range want {
302			r := got.Results[i]
303			if r.OK || r.Error != "invalid" || !strings.Contains(r.Reason, sub) {
304				t.Fatalf("result %d: want invalid containing %q, got %+v", i, sub, r)
305			}
306			if r.ExpectedRevision != 0 || r.ActualRevision != 0 {
