609		// One instance keeps its id but gets a new address: the registration bumps
610		// once, that instance resets to unknown/0 while untouched instances keep
611		// their observations, and the rotation continues after the last chosen id
612		// instead of restarting at the smallest id.
613		input := `{"requests":[
614			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"},{"id":"d","address":"h4:4"}]},
