653		// it did not restart from the smallest id because of the replacement.
654		if r := got.Results[9]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 || r.Revision != 2 {
655			t.Fatalf("select should wrap to smallest eligible id: %+v", r)
656		}
